// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

contract MultiTokenBridge {
    address public immutable owner;
    mapping(address => bool) public validators;
    mapping(bytes32 => bool) public processedTransfers;
    mapping(address => mapping(address => uint256)) public lockedBalances;
    uint256 public validatorCount;
    uint256 public requiredConfirmations;

    event TransferInitiated(bytes32 indexed transferId, address token, address sender, uint256 amount, bytes destinationAddress, bytes destinationChain);
    event TransferCompleted(bytes32 indexed transferId, address token, address recipient, uint256 amount);

    modifier onlyOwner() {
        require(msg.sender == owner, "Not owner");
        _;
    }

    modifier onlyValidator() {
        require(validators[msg.sender], "Not validator");
        _;
    }

    constructor(uint256 _requiredConfirmations) {
        owner = msg.sender;
        requiredConfirmations = _requiredConfirmations;
    }

    function addValidator(address validator) external onlyOwner {
        require(!validators[validator], "Already validator");
        validators[validator] = true;
        validatorCount++;
    }

    function removeValidator(address validator) external onlyOwner {
        require(validators[validator], "Not a validator");
        validators[validator] = false;
        validatorCount--;
    }

    function lockTokens(
        address token,
        uint256 amount,
        bytes calldata destinationAddress,
        bytes calldata destinationChain
    ) external {
        require(amount > 0, "Zero amount");
        require(destinationAddress.length > 0, "Empty destination");
        require(destinationChain.length > 0, "Empty chain");

        // Transfer tokens to this contract
        (bool success, bytes memory data) = token.call(
            abi.encodeWithSelector(0x23b872dd, msg.sender, address(this), amount)
        );
        require(success && (data.length == 0 || abi.decode(data, (bool))), "Transfer failed");

        lockedBalances[token][msg.sender] += amount;

        bytes32 transferId = _computeTransferId(
            token, msg.sender, amount, destinationAddress, destinationChain
        );

        emit TransferInitiated(transferId, token, msg.sender, amount, destinationAddress, destinationChain);
    }

    function completeTransfer(
        address token,
        address recipient,
        uint256 amount,
        bytes calldata sourceAddress,
        bytes calldata sourceChain,
        bytes[] calldata signatures
    ) external onlyValidator {
        require(signatures.length >= requiredConfirmations, "Insufficient confirmations");

        bytes32 transferId = _computeTransferId(
            token, recipient, amount, sourceAddress, sourceChain
        );

        require(!processedTransfers[transferId], "Already processed");

        // Verify unique validator signatures
        address[] memory signers = new address[](signatures.length);
        for (uint256 i = 0; i < signatures.length; i++) {
            address signer = _recoverSigner(transferId, signatures[i]);
            require(validators[signer], "Invalid signer");
            for (uint256 j = 0; j < i; j++) {
                require(signers[j] != signer, "Duplicate signer");
            }
            signers[i] = signer;
        }

        processedTransfers[transferId] = true;

        // Release tokens
        (bool success, bytes memory data) = token.call(
            abi.encodeWithSelector(0xa9059cbb, recipient, amount)
        );
        require(success && (data.length == 0 || abi.decode(data, (bool))), "Transfer failed");

        emit TransferCompleted(transferId, token, recipient, amount);
    }

    function _computeTransferId(
        address token,
        address account,
        uint256 amount,
        bytes calldata extraData1,
        bytes calldata extraData2
    ) internal view returns (bytes32) {
        return keccak256(
            abi.encodePacked(
                address(this),
                block.chainid,
                token,
                account,
                amount,
                extraData1,
                extraData2
            )
        );
    }

    function _recoverSigner(bytes32 hash, bytes memory signature) internal pure returns (address) {
        require(signature.length == 65, "Invalid signature length");
        bytes32 r;
        bytes32 s;
        uint8 v;
        assembly {
            r := mload(add(signature, 32))
            s := mload(add(signature, 64))
            v := byte(0, mload(add(signature, 96)))
        }
        require(uint256(s) <= 0x7FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF5D576E7357A4501DDFE92F46681B20A0, "Invalid s");
        require(v == 27 || v == 28, "Invalid v");
        bytes32 prefixedHash = keccak256(abi.encodePacked("\x19Ethereum Signed Message:\n32", hash));
        address signer = ecrecover(prefixedHash, v, r, s);
        require(signer != address(0), "Invalid signature");
        return signer;
    }
}
